/** The guard predicates of the appointment machine, implemented once by the domain (AppointmentGuards). */
@Suppress("TooManyFunctions")
interface AppointmentPredicates {
    /**
     * the command's target slot exists in the schedule of the appointment's resource, is not entered in error and ends after now (a running
     * session counts, so a same-day booking into a session that has started is possible); and either it is free, or it is tentatively held
     * or booked by this same appointment, or it is marked overbookable and its count of overbooked appointments is strictly less than its
     * overbook cap (§9.2 'capped overbooking'; integers, exact comparison). A slot whose status is busy-unavailable is never available. The
     * cap is configuration [HUMAN]; a missing cap counts as zero
     */
    fun slotAvailable(facts: AppointmentFacts): Boolean

    /**
     * the command's target slot differs from the slot the appointment currently holds or books, so a reschedule always moves the
     * appointment
     */
    fun differentSlotRequested(facts: AppointmentFacts): Boolean

    /**
     * every participant marked required on the appointment (patient, practitioner, location, equipment; R11 §4) has the response accepted
     * for the command's target slot (R11 §4 'AppointmentResponse: participant accept/decline'); a response given for an earlier slot does
     * not count
     */
    fun requiredParticipantsAccepted(facts: AppointmentFacts): Boolean

    /** the exact complement of requiredParticipantsAccepted */
    fun participantAcceptanceAwaited(facts: AppointmentFacts): Boolean

    /**
     * the appointment carries complete waitlist constraints and a priority (R11 §4 'Waitlist entry: constraints (provider, time windows),
     * priority, auto-offer rules'): a service type; a set of acceptable providers (empty means any provider of the service); a set of
     * acceptable locations (empty means any location); an earliest and a latest acceptable date with earliest on or before latest and
     * latest on or after today; and a priority code from the tenant's governed waitlist-priority list [HUMAN], chosen by the user (never
     * defaulted). Only date ranges are modelled, not time-of-day windows (DN-057 item 8)
     */
    fun waitlistEntryComplete(facts: AppointmentFacts): Boolean

    /**
     * the offered slot satisfies this entry's waitlist constraints: the slot's service type equals the entry's; its provider is in the
     * entry's provider set, or the set is empty; its location is in the entry's location set, or the set is empty; its date is on or after
     * the earliest and on or before the latest acceptable date; and this entry has not already declined this slot, nor let an offer of it
     * lapse after the offer's delivery was confirmed (a lapse without confirmed delivery does not count against the entry)
     */
    fun offeredSlotMatchesConstraints(facts: AppointmentFacts): Boolean

    /**
     * among the competing waitlist entries the facts list for this slot (every other entry whose constraints match the slot, as
     * offeredSlotMatchesConstraints reads them), none ranks before this entry. An entry ranks before another when its priority rank is
     * lower (the rank comes from the governed priority list), or the ranks are equal and it was waitlisted earlier, or both are equal and
     * its entry id sorts first (a total, deterministic order; DN-057 item 8). A priority code outside the governed list has no rank: this
     * entry is then never top ranked, and a competitor without a rank ranks before it, so an entry of unknown priority is never passed over
     * silently
     */
    fun topRankedForSlot(facts: AppointmentFacts): Boolean

    /** the appointment is in pending because of a waitlist offer (OfferSlot), not because a booking awaits a participant's acceptance */
    fun waitlistOffer(facts: AppointmentFacts): Boolean

    /** the exact complement of waitlistOffer */
    fun notWaitlistOffer(facts: AppointmentFacts): Boolean

    /**
     * the pending hold has a respond-by instant and now is strictly before it. The respond-by instant is fixed when the hold is created
     * (Book into pending, OfferSlot, Reschedule into pending) from tenant configuration [HUMAN]: the offer deadline for a waitlist offer,
     * the acceptance deadline for any other hold
     */
    fun holdResponseWindowOpen(facts: AppointmentFacts): Boolean

    /**
     * the exact complement of holdResponseWindowOpen: now is at or after the hold's respond-by instant, or the hold has none (a missing
     * deadline lapses the hold, so a slot is never held without a limit)
     */
    fun holdResponseWindowElapsed(facts: AppointmentFacts): Boolean

    /** the waitlist entry's latest acceptable date is strictly before today (tenant-calendar date), so no slot can satisfy it any longer */
    fun waitlistWindowEnded(facts: AppointmentFacts): Boolean

    /**
     * two identifiers of the person checking in were confirmed against the appointment's patient (SI-01 clauses a and d; CTRL-0001-3;
     * DN-057 item 3), each from what the patient or companion states or presents, never from confirming a value the desk reads from the
     * screen: (1) the name the patient states matches a name form of the record, by empi's cross-script matching answer (Kurdish, Arabic,
     * Latin), never a desk judgement; and (2) the MRN with a valid check digit (empi's answer) equals the patient's MRN, where the MRN came
     * from a card or wristband scan or was stated by the patient, or, for a patient without a card, from an empi search on the stated name
     * and the stated date of birth that returned exactly one candidate, the appointment's patient (DN-057 item 4; several or no candidates
     * refuse, and the patient goes to the registration desk); and (3) the date of birth the patient states equals the record's at its
     * recorded precision, or, when the record carries the approximate-DOB flag, the approximate age or birth year the patient states
     * matches it by empi's answer. A room, bed, token or appointment number is never an identifier. A record whose MRN or date of birth (or
     * approximate-DOB flag) is missing fails
     */
    fun patientIdentifiedByTwoIdentifiers(facts: AppointmentFacts): Boolean

    /**
     * now is at or after the appointment's slot start minus the tenant's early check-in window and strictly before the end of the slot's
     * session (the clinic session the slot belongs to, which may run past midnight for evening clinics, §9.3); the window is configuration
     * [HUMAN], a missing window counts as zero
     */
    fun withinCheckInWindow(facts: AppointmentFacts): Boolean

    /**
     * a session of the requested service (and provider, when one is requested) that accepts walk-ins is running now: now is at or after its
     * start and strictly before its end, from the schedule (no capacity limit is applied here; a walk-in cap is not a guard of this
     * machine)
     */
    fun walkInSessionOpen(facts: AppointmentFacts): Boolean

    /**
     * the linked outpatient encounter (adt's answer) is not cancelled or entered in error, and either the record module reports a
     * consultation recorded for it, or adt reports it in discharged-not-closed or finished with a disposition other than
     * left-without-being-seen. Encounter states are the encounter machine's: planned, arrived, triaged, in-progress, on-leave,
     * discharged-not-closed, finished, cancelled, entered-in-error; an OPD visit ends through arrived or triaged → discharged-not-closed
     * (encounter.md Q-E2)
     */
    fun consultationCompleted(facts: AppointmentFacts): Boolean

    /**
     * the linked encounter (adt's answer) is cancelled or entered in error, or is in discharged-not-closed or finished with the disposition
     * left-without-being-seen, and the record module reports no consultation recorded for it. Disjoint from consultationCompleted
     */
    fun linkedEncounterEndedWithoutConsultation(facts: AppointmentFacts): Boolean

    /**
     * the command carries a cancellation reason that the acting user chose (§9.2 'reason-coded cancellations'; §8.4 'why'): a code of the
     * tenant's governed cancellation-reason list [HUMAN], marked by the channel as chosen by the user, never prefilled, defaulted or
     * carried over; a code that requires text (for example 'other') has non-blank text
     */
    fun cancellationReasonGiven(facts: AppointmentFacts): Boolean

    /**
     * the command records who cancelled (§8.4 'by whom'): the requesting party (patient or their representative, practitioner, hospital)
     * and who entered it: an authenticated user (a Trust Plane answer), or for a patient's own cancellation through a front-door link, the
     * link's verified patient session (§9.30 booking links)
     */
    fun cancellingPartyRecorded(facts: AppointmentFacts): Boolean

    /**
     * the cancellation ends the patient's need for this visit: the requesting party is the patient or their representative, or the reason
     * code is one the governed list marks as ending the need (for example 'no longer clinically required'); a hospital or practitioner
     * reason of capacity (clinic cancelled, practitioner unavailable) does not
     */
    fun cancellationEndsNeed(facts: AppointmentFacts): Boolean

    /**
     * the exact complement of cancellationEndsNeed: a hospital or practitioner cancellation whose reason does not end the need, so the
     * request must be rebooked (DN-057 item 6)
     */
    fun cancellationNeedsRebooking(facts: AppointmentFacts): Boolean

    /**
     * the tenant's late-cancel window is greater than zero, the appointment has a start instant, and now is at or after that start minus
     * the window (a cancellation after the start counts as late). A window of zero means no cancellation is ever late (§8.4 'late-cancel
     * flag'; configuration [HUMAN]; DN-057 item 7)
     */
    fun lateCancellation(facts: AppointmentFacts): Boolean

    /** the exact complement of lateCancellation */
    fun timelyCancellation(facts: AppointmentFacts): Boolean

    /**
     * the appointment has a slot end instant and now is at or after that end plus the tenant's no-show grace period (configuration [HUMAN];
     * a missing period counts as zero). Measured from the slot end, never its start, so a patient arriving within a session clinic's slot
     * is never a no-show
     */
    fun noShowGraceElapsed(facts: AppointmentFacts): Boolean

    /**
     * the command carries a no-show reason that the acting user chose (§9.2 'reason-coded ... no-shows'): a code of the tenant's governed
     * no-show-reason list [HUMAN] (which may include 'not contacted, reason unknown'), entered by an authenticated user, never prefilled or
     * defaulted
     */
    fun noShowReasonGiven(facts: AppointmentFacts): Boolean

    /**
     * adt reports an encounter of the patient that is open (not discharged-not-closed, finished, cancelled or entered in error) and is an
     * ED or inpatient encounter overlapping the slot time, so the patient could not attend. When the appointment's slot start or end is
     * unknown, every open ED or inpatient encounter counts, so an unknown slot time never allows a no-show
     */
    fun patientInHospital(facts: AppointmentFacts): Boolean

    /** the exact complement of patientInHospital */
    fun patientNotInHospital(facts: AppointmentFacts): Boolean

    /**
     * the modification changes none of the appointment's slot, start, end, scheduled resource or location (those are a reschedule) and
     * changes at least one other attribute (reason, service type within the slot's service, notes, interpreter need, participants who are
     * not scheduled resources, priority or constraints of a waitlist entry)
     */
    fun modificationKeepsSlot(facts: AppointmentFacts): Boolean

    /**
     * the user holds the privilege for this correction (a Trust Plane answer; a same-day ReverseNoShow needs only the front-desk reversal
     * privilege, DN-057 item 9) and the action is audited: the audit record of the correction can be written with it (an audit outage
     * refuses the command; it never runs unaudited)
     */
    fun privilegedAndAudited(facts: AppointmentFacts): Boolean

    /** the command carries a correction reason that the user entered (never prefilled or defaulted) */
    fun correctionReasonEntered(facts: AppointmentFacts): Boolean
}

