    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: AppointmentPredicate,
        predicates: AppointmentPredicates,
        facts: AppointmentFacts,
    ): Boolean =
        when (predicate) {
            AppointmentPredicate.SLOT_AVAILABLE -> predicates.slotAvailable(facts)
            AppointmentPredicate.DIFFERENT_SLOT_REQUESTED -> predicates.differentSlotRequested(facts)
            AppointmentPredicate.REQUIRED_PARTICIPANTS_ACCEPTED -> predicates.requiredParticipantsAccepted(facts)
            AppointmentPredicate.PARTICIPANT_ACCEPTANCE_AWAITED -> predicates.participantAcceptanceAwaited(facts)
            AppointmentPredicate.WAITLIST_ENTRY_COMPLETE -> predicates.waitlistEntryComplete(facts)
            AppointmentPredicate.OFFERED_SLOT_MATCHES_CONSTRAINTS -> predicates.offeredSlotMatchesConstraints(facts)
            AppointmentPredicate.TOP_RANKED_FOR_SLOT -> predicates.topRankedForSlot(facts)
            AppointmentPredicate.WAITLIST_OFFER -> predicates.waitlistOffer(facts)
            AppointmentPredicate.NOT_WAITLIST_OFFER -> predicates.notWaitlistOffer(facts)
            AppointmentPredicate.HOLD_RESPONSE_WINDOW_OPEN -> predicates.holdResponseWindowOpen(facts)
            AppointmentPredicate.HOLD_RESPONSE_WINDOW_ELAPSED -> predicates.holdResponseWindowElapsed(facts)
            AppointmentPredicate.WAITLIST_WINDOW_ENDED -> predicates.waitlistWindowEnded(facts)
            AppointmentPredicate.PATIENT_IDENTIFIED_BY_TWO_IDENTIFIERS -> predicates.patientIdentifiedByTwoIdentifiers(facts)
            AppointmentPredicate.WITHIN_CHECK_IN_WINDOW -> predicates.withinCheckInWindow(facts)
            AppointmentPredicate.WALK_IN_SESSION_OPEN -> predicates.walkInSessionOpen(facts)
            AppointmentPredicate.CONSULTATION_COMPLETED -> predicates.consultationCompleted(facts)
            AppointmentPredicate.LINKED_ENCOUNTER_ENDED_WITHOUT_CONSULTATION -> predicates.linkedEncounterEndedWithoutConsultation(facts)
            AppointmentPredicate.CANCELLATION_REASON_GIVEN -> predicates.cancellationReasonGiven(facts)
            AppointmentPredicate.CANCELLING_PARTY_RECORDED -> predicates.cancellingPartyRecorded(facts)
            AppointmentPredicate.CANCELLATION_ENDS_NEED -> predicates.cancellationEndsNeed(facts)
            AppointmentPredicate.CANCELLATION_NEEDS_REBOOKING -> predicates.cancellationNeedsRebooking(facts)
            AppointmentPredicate.LATE_CANCELLATION -> predicates.lateCancellation(facts)
            AppointmentPredicate.TIMELY_CANCELLATION -> predicates.timelyCancellation(facts)
            AppointmentPredicate.NO_SHOW_GRACE_ELAPSED -> predicates.noShowGraceElapsed(facts)
            AppointmentPredicate.NO_SHOW_REASON_GIVEN -> predicates.noShowReasonGiven(facts)
            AppointmentPredicate.PATIENT_IN_HOSPITAL -> predicates.patientInHospital(facts)
            AppointmentPredicate.PATIENT_NOT_IN_HOSPITAL -> predicates.patientNotInHospital(facts)
            AppointmentPredicate.MODIFICATION_KEEPS_SLOT -> predicates.modificationKeepsSlot(facts)
            AppointmentPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            AppointmentPredicate.CORRECTION_REASON_ENTERED -> predicates.correctionReasonEntered(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: AppointmentState,
        command: AppointmentCommand,
        predicates: AppointmentPredicates,
        facts: AppointmentFacts,
    ): Outcome<AppointmentState, AppointmentCommand, AppointmentPredicate, AppointmentEffect> =
        spec.fire(state, command) { holds(it, predicates, facts) }
}
